&lt;tr&gt;
&lt;td&gt;Latest version&lt;/td&gt;
&lt;td&gt;v2.2.0.3&lt;/td&gt;
&lt;td&gt;1.4.3&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Docker image&lt;/td&gt;
&lt;td&gt;&lt;code&gt;lscr.io/linuxserver/duplicati:2.2.0&lt;/code&gt;&lt;/td&gt;
&lt;td&gt;
&lt;code&gt;b3vis/borgbackup:1.4.3&lt;/code&gt; (community)&lt;/td&gt;
&lt;/tr&gt;
&lt;tr&gt;
&lt;td&gt;Language&lt;/td&gt;
